const modal=document.getElementById('statusModal');const modalProvaIdInput=document.getElementById('modalProvaId');const modalNovoStatusInput=document.getElementById('modalNovoStatus');const modalMotivoTextarea=document.getElementById('modalMotivo');function openStatusModal(button){const provaId=button.getAttribute('data-prova-id');const novoStatus=button.getAttribute('data-novo-status');modalProvaIdInput.value=provaId;modalNovoStatusInput.value=novoStatus;modalMotivoTextarea.value='';modal.style.display='flex';modalMotivoTextarea.focus();}function closeStatusModal(){modal.style.display='none';}